CustomField.formula:
IF(NOT(ISBLANK(SBQQ__RenewedSubscription__c)) && SBQQ__Quantity__c != 0,
    IF( Price_Change__c ,"Price Change","Renewal"),
    IF(ISBLANK(SBQQ__UpgradedSubscription__c) && ISBLANK(SBQQ__RenewedSubscription__c),
        IF( Price_Change__c ,"Price Change","New"),
        IF(SBQQ__Quantity__c = 0,
            IF( Price_Change__c ,"Cancellation Price Change","Cancellation"),
            IF(SBQQ__Quantity__c > SBQQ__UpgradedSubscription__r.SBQQ__Quantity__c,
                "Quantity Increase",
                IF(SBQQ__Quantity__c < SBQQ__UpgradedSubscription__r.SBQQ__Quantity__c,
                    "Quantity Reduction",
                    "Amendment"
                )
            )
        )        
    )
)
